-- External recruitment is an evidence inbox, never a second employee master.
CREATE TABLE ty_rc_channel(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 requisition_id bigint NOT NULL REFERENCES ty_hr_requisition(id),
 provider text NOT NULL CHECK(provider IN('feishu_hire','file')),
 connection_id bigint REFERENCES ty_integration_connection(id),
 external_tenant text NOT NULL,external_job_id text NOT NULL,name text NOT NULL,
 evidence_ref text NOT NULL,authorized_until timestamptz NOT NULL,
 connection_revision integer,secret_revision integer,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','disabled')),
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),
 revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),
 CHECK((provider='file' AND connection_id IS NULL)OR(provider='feishu_hire' AND connection_id IS NOT NULL)),
 CHECK(status<>'active' OR approved_by IS NOT NULL),
 UNIQUE(group_id,provider,external_tenant,external_job_id)
);
CREATE TABLE ty_rc_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,channel_id bigint NOT NULL REFERENCES ty_rc_channel(id),
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 request jsonb NOT NULL,input_hash text NOT NULL,source_key text NOT NULL,
 channel_revision integer NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),
 state text NOT NULL DEFAULT 'queued' CHECK(state IN('queued','leased','completed','blocked','failed','cancelled')),
 lease_token text,lease_until timestamptz,attempts integer NOT NULL DEFAULT 0,
 error_code text,result jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,
 CHECK((state='leased')=(lease_token IS NOT NULL AND lease_until IS NOT NULL)),
 UNIQUE(channel_id,source_key)
);
CREATE TABLE ty_rc_root(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,channel_id bigint NOT NULL REFERENCES ty_rc_channel(id),
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 external_id text NOT NULL,external_talent_id text NOT NULL,
 latest_version_id bigint,reviewed_version_id bigint,conflict_version_id bigint,native_candidate_id bigint UNIQUE REFERENCES ty_hr_candidate(id),
 revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(channel_id,external_id)
);
CREATE TABLE ty_rc_version(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_id bigint NOT NULL REFERENCES ty_rc_root(id),
 source_version text NOT NULL,source_at_ms bigint NOT NULL CHECK(source_at_ms BETWEEN 0 AND 4102444800000),
 source_hash text NOT NULL CHECK(source_hash~'^[a-f0-9]{64}$'),
 source_state text NOT NULL CHECK(source_state IN('active','inactive','withdrawn')),
 disposition text NOT NULL CHECK(disposition IN('current','stale','conflict')),
 payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 original_cipher bytea,original_iv text,original_tag text,filename text,mime text,original_hash text,byte_length integer,
 job_id bigint REFERENCES ty_rc_job(id),created_by bigint NOT NULL REFERENCES sys_account(id),
 created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(num_nonnulls(original_cipher,original_iv,original_tag,filename,mime,original_hash,byte_length)IN(0,7)),
 CHECK(original_cipher IS NULL OR octet_length(original_cipher)=byte_length),
 UNIQUE(root_id,source_version),UNIQUE(root_id,source_hash)
);
ALTER TABLE ty_rc_root ADD FOREIGN KEY(latest_version_id)REFERENCES ty_rc_version(id);
ALTER TABLE ty_rc_root ADD FOREIGN KEY(reviewed_version_id)REFERENCES ty_rc_version(id);
ALTER TABLE ty_rc_root ADD FOREIGN KEY(conflict_version_id)REFERENCES ty_rc_version(id);
CREATE TABLE ty_rc_review(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,root_id bigint NOT NULL REFERENCES ty_rc_root(id),
 version_id bigint NOT NULL REFERENCES ty_rc_version(id),native_candidate_id bigint REFERENCES ty_hr_candidate(id),
 decision text NOT NULL CHECK(decision IN('accepted','updated','rejected','withdrawal_acknowledged')),
 reason text NOT NULL,created_by bigint NOT NULL REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(root_id,version_id,decision)
);
CREATE FUNCTION fn_ty_rc_scope_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_rc_channel%ROWTYPE;r public.ty_rc_root%ROWTYPE;q public.ty_hr_requisition%ROWTYPE;i public.ty_integration_connection%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='ty_rc_channel' THEN
  SELECT*INTO q FROM public.ty_hr_requisition WHERE id=NEW.requisition_id;
  IF q.id IS NULL OR q.group_id<>NEW.group_id OR q.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源必须对应同一公司招聘需求';END IF;
  IF NEW.connection_id IS NOT NULL THEN
   SELECT*INTO i FROM public.ty_integration_connection WHERE id=NEW.connection_id;
   IF i.id IS NULL OR i.group_id<>NEW.group_id OR i.provider<>'feishu' OR(i.company_id IS NOT NULL AND i.company_id<>NEW.company_id) OR i.config->>'organization_id' IS DISTINCT FROM NEW.external_tenant THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 外部企业与飞书连接不一致';END IF;
  END IF;
  IF NEW.status='active'AND public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 来源映射须不同人员独立核准';END IF;
  IF TG_OP='UPDATE'AND (NEW.group_id,NEW.company_id,NEW.requisition_id,NEW.provider,NEW.connection_id,NEW.external_tenant,NEW.external_job_id,NEW.created_by,NEW.authorized_until,NEW.evidence_ref)IS DISTINCT FROM(OLD.group_id,OLD.company_id,OLD.requisition_id,OLD.provider,OLD.connection_id,OLD.external_tenant,OLD.external_job_id,OLD.created_by,OLD.authorized_until,OLD.evidence_ref)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源映射不可改绑；重新建有据授权';END IF;
 ELSIF TG_TABLE_NAME IN('ty_rc_root','ty_rc_job')THEN
  SELECT*INTO c FROM public.ty_rc_channel WHERE id=NEW.channel_id;
  IF c.id IS NULL OR c.group_id<>NEW.group_id OR c.company_id<>NEW.company_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源根和采集任务范围不一致';END IF;
  IF TG_TABLE_NAME='ty_rc_root'THEN
   IF TG_OP='UPDATE'AND(NEW.channel_id,NEW.group_id,NEW.company_id,NEW.external_id,NEW.external_talent_id)IS DISTINCT FROM(OLD.channel_id,OLD.group_id,OLD.company_id,OLD.external_id,OLD.external_talent_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源稳定身份不可改绑';END IF;
   IF NEW.native_candidate_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_hr_candidate x WHERE x.id=NEW.native_candidate_id AND x.requisition_id=c.requisition_id AND x.group_id=c.group_id AND x.company_id=c.company_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 只能接入同一需求的原生候选';END IF;
   IF TG_OP='UPDATE'AND OLD.native_candidate_id IS NOT NULL AND NEW.native_candidate_id IS DISTINCT FROM OLD.native_candidate_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已接收候选不可换人或解绑';END IF;
   IF NEW.latest_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.latest_version_id AND v.root_id=NEW.id AND v.disposition='current')OR NEW.reviewed_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.reviewed_version_id AND v.root_id=NEW.id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源版本不属于当前来源根';END IF;
   IF NEW.conflict_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.conflict_version_id AND v.root_id=NEW.id AND v.disposition='conflict')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 冲突版本不属于当前来源根';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='ty_rc_version'THEN
  SELECT*INTO r FROM public.ty_rc_root WHERE id=NEW.root_id;SELECT*INTO c FROM public.ty_rc_channel WHERE id=r.channel_id;
  IF c.provider='feishu_hire'AND(NEW.job_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.ty_rc_job x WHERE x.id=NEW.job_id AND x.channel_id=c.id AND x.created_by=NEW.created_by AND x.state='leased'))OR c.provider='file'AND NEW.job_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台来源必须有同一企业职位的真实受限采集任务；文件来源不伪装平台回执';END IF;
 ELSIF TG_TABLE_NAME='ty_rc_review'THEN
  SELECT*INTO r FROM public.ty_rc_root WHERE id=NEW.root_id;
  IF NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.version_id AND v.root_id=r.id)OR NEW.native_candidate_id IS DISTINCT FROM r.native_candidate_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 人工核对凭据与来源候选不一致';END IF;
  IF EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.version_id AND public.fn_ty_pr_same_actor(v.created_by,NEW.created_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 来源原件须不同人员核对';END IF;
  IF NEW.decision IN('accepted','updated')AND(NEW.native_candidate_id IS NULL OR NEW.version_id<>r.latest_version_id OR NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.version_id AND v.source_state='active'))OR NEW.decision='rejected'AND NEW.native_candidate_id IS NOT NULL OR NEW.decision='withdrawal_acknowledged'AND NOT EXISTS(SELECT 1 FROM public.ty_rc_version v WHERE v.id=NEW.version_id AND v.source_state IN('inactive','withdrawn'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 人工核对结论与当前来源状态不一致';END IF;
 END IF;RETURN NEW;
END$$;
CREATE TRIGGER ty_rc_channel_scope BEFORE INSERT OR UPDATE ON ty_rc_channel FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_scope_guard();
CREATE TRIGGER ty_rc_root_scope BEFORE INSERT OR UPDATE ON ty_rc_root FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_scope_guard();
CREATE TRIGGER ty_rc_job_scope BEFORE INSERT OR UPDATE ON ty_rc_job FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_scope_guard();
CREATE TRIGGER ty_rc_review_scope BEFORE INSERT ON ty_rc_review FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_scope_guard();
CREATE TRIGGER ty_rc_version_scope BEFORE INSERT ON ty_rc_version FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_scope_guard();
CREATE FUNCTION fn_ty_rc_review_proof()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_rc_root%ROWTYPE;
BEGIN SELECT*INTO r FROM public.ty_rc_root WHERE id=NEW.id;
 IF r.native_candidate_id IS NOT NULL AND r.reviewed_version_id IS NULL OR r.reviewed_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_rc_review p WHERE p.root_id=r.id AND p.version_id=r.reviewed_version_id AND p.native_candidate_id=r.native_candidate_id AND p.decision IN('accepted','updated'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原生候选接收或更新缺少明确人工核对凭据';END IF;
 RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER ty_rc_review_proof AFTER INSERT OR UPDATE ON ty_rc_root DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_review_proof();
CREATE FUNCTION fn_ty_rc_immutable()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 来源原件、版本和人工核对记录只追加保留';END$$;
CREATE TRIGGER ty_rc_version_immutable BEFORE UPDATE OR DELETE ON ty_rc_version FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_immutable();
CREATE TRIGGER ty_rc_review_immutable BEFORE UPDATE OR DELETE ON ty_rc_review FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_immutable();
CREATE FUNCTION fn_ty_rc_offer_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_rc_root%ROWTYPE;v public.ty_rc_version%ROWTYPE;c public.ty_rc_channel%ROWTYPE;
BEGIN
 IF NEW.status IN('declined','withdrawn')THEN RETURN NEW;END IF;
 SELECT*INTO r FROM public.ty_rc_root WHERE native_candidate_id=NEW.candidate_id;
 IF r.id IS NULL THEN RETURN NEW;END IF;
 SELECT*INTO v FROM public.ty_rc_version WHERE id=r.latest_version_id;
 SELECT*INTO c FROM public.ty_rc_channel WHERE id=r.channel_id;
 IF r.conflict_version_id IS NOT NULL OR r.reviewed_version_id IS DISTINCT FROM r.latest_version_id OR v.source_state<>'active' OR c.status<>'active' OR c.authorized_until<=clock_timestamp()THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 外部来源更新、撤回或授权变化，须先人工核对；不能继续Offer或入职';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sys_account a WHERE a.id=c.approved_by AND a.status='active')OR c.provider='feishu_hire'AND NOT EXISTS(SELECT 1 FROM public.ty_integration_connection i WHERE i.id=c.connection_id AND i.status='active'AND i.revision=c.connection_revision AND i.secret_revision=c.secret_revision AND i.config->>'organization_id'=c.external_tenant)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 外部企业连接、凭据或核准人已变化，原授权不再适用';END IF;
 RETURN NEW;
END$$;
CREATE TRIGGER ty_rc_offer_guard BEFORE INSERT OR UPDATE ON ty_hr_offer FOR EACH ROW EXECUTE FUNCTION fn_ty_rc_offer_guard();
CREATE INDEX ty_rc_source_lookup ON ty_rc_root(group_id,company_id,id);
CREATE INDEX ty_rc_queue ON ty_rc_job(state,id);
